/* Generated by tools/build_lines.py from picks/hyd.txt. Every line is from: NCERT XI Part 2 (old). Do not edit by hand. */
(function () {
  const R = window.RES;
  R.addLines("hyd", "NCERT XI Part 2 (old)", [{"sec": "Position in the periodic table","ids": [40,41,42],"t": "Simplest atom: one proton, one electron; elemental form is diatomic H2 (dihydrogen).","exc": false,"tab": false,"src": "old11","page": 25,"o": "Hydrogen has the simplest atomic structure among all the elements around us in Nature. In atomic form it consists of only one proton and one electron. However, in elemental form it exists as a diatomic (H2) molecule and is called dihydrogen."},{"sec": "Position in the periodic table","ids": [43],"t": "Forms more compounds than any other element.","exc": false,"tab": false,"src": "old11","page": 25,"o": "It forms more compounds than any other element."},{"sec": "Position in the periodic table","ids": [47,48,49],"t": "H is 1s^1: like alkali metals (ns^1), and like halogens (ns^2np^5) it is one electron short of a noble gas (He, 1s^2).","exc": false,"tab": false,"src": "old11","page": 25,"o": "Hydrogen has electronic configuration 1s^1. On one hand, its electronic configuration is similar to the outer electronic configuration (ns^1) of alkali metals, which belong to the first group of the periodic table. On the other hand, like halogens (with ns^2np^5 configuration belonging to the seventeenth group of the periodic table), it is short by one electron to the corresponding noble gas configuration, helium (1s^2)."},{"sec": "Position in the periodic table","ids": [50],"t": "So it resembles alkali metals (forms H^+) and halogens (forms H^–).","exc": false,"tab": false,"src": "old11","page": 25,"o": "Hydrogen, therefore, has resemblance to alkali metals, which lose one electron to form unipositive ions, as well as with halogens, which gain one electron to form uninegative ion."},{"sec": "Position in the periodic table","ids": [51],"t": "Like alkali metals: forms oxides, halides, sulphides.","exc": false,"tab": false,"src": "old11","page": 25,"o": "Like alkali metals, hydrogen forms oxides, halides and sulphides."},{"sec": "Position in the periodic table","ids": [52,53],"t": "Unlike alkali metals: very high ionization enthalpy, no metallic character under normal conditions.","exc": true,"tab": false,"src": "old11","page": 25,"o": "However, unlike alkali metals, it has a very high ionization enthalpy and does not possess metallic characteristics under normal conditions."},{"sec": "Position in the periodic table","ids": [54],"t": "In ionization enthalpy it resembles halogens: ∆iH Li 520, H 1312, F 1680 kJ mol^-1.","exc": true,"tab": false,"src": "old11","page": 26,"o": "In fact, in terms of ionization enthalpy, hydrogen resembles more with halogens, ∆iH of Li is 520 kJ mol^-1, F is 1680 kJ mol^-1 and that of H is 1312 kJ mol^-1."},{"sec": "Position in the periodic table","ids": [55,56],"t": "Like halogens: diatomic, forms hydrides and many covalent compounds; but far less reactive than halogens.","exc": false,"tab": false,"src": "old11","page": 26,"o": "Like halogens, it forms a diatomic molecule, combines with elements to form hydrides and a large number of covalent compounds. However, in terms of reactivity, it is very low as compared to halogens."},{"sec": "Position in the periodic table","ids": [59,60,61],"t": "H^+ (bare nucleus, ~1.5×10^-3 pm) is tiny vs normal sizes (50–200 pm), so **H^+ never exists free**; it is always associated with other atoms or molecules.","exc": false,"tab": false,"src": "old11","page": 26,"o": "Loss of the electron from hydrogen atom results in nucleus (H^+) of ~1.5×10^-3 pm size. This is extremely small as compared to normal atomic and ionic sizes of 50 to 200pm. As a consequence, H^+ does not exist freely and is always associated with other atoms or molecules."},{"sec": "Position in the periodic table","ids": [62],"t": "Unique behaviour, so best placed separately in the periodic table.","exc": false,"tab": false,"src": "old11","page": 26,"o": "Thus, it is unique in behaviour and is, therefore, best placed separately in the periodic table."},{"sec": "Occurrence and isotopes","ids": [63,64,74],"t": "H is the most abundant element in the universe (70% of total mass) and the principal element of the solar atmosphere.","exc": false,"tab": true,"src": "old11","page": 26,"o": "Dihydrogen is the most abundant element in the universe (70% of the total mass of the universe) and is the principal element in the solar atmosphere. The giant planets Jupiter and Saturn consist mostly of hydrogen."},{"sec": "Occurrence and isotopes","ids": [65,66],"t": "Only 0.15% by mass of the earth's atmosphere (it is light); 15.4% of crust and oceans in combined form.","exc": false,"tab": false,"src": "old11","page": 26,"o": "However, due to its light nature, it is much less abundant (0.15% by mass) in the earth's atmosphere. Of course, in the combined form it constitutes 15.4% of the earth's crust and the oceans."},{"sec": "Occurrence and isotopes","ids": [68,70],"t": "Isotopes: protium ^1H (0 neutrons), deuterium ^2H = D (1), tritium ^3H = T (2).","exc": false,"tab": false,"src": "old11","page": 26,"o": "Hydrogen has three isotopes: protium, ^1H, deuterium, ^2H or D and tritium, ^3H or T. Ordinary hydrogen, protium, has no neutrons, deuterium (also known as heavy hydrogen) has one and tritium has two neutrons in the nucleus."},{"sec": "Occurrence and isotopes","ids": [72,73],"t": "Protium predominates; D is 0.0156% (mostly as HD); T ≈ 1 atom per 10^18 H.","exc": false,"tab": false,"src": "old11","page": 26,"o": "The predominant form is protium. Terrestrial hydrogen contains 0.0156% of deuterium mostly in the form of HD. The tritium concentration is about one atom per 10^18 atoms of protium."},{"sec": "Occurrence and isotopes","ids": [74],"t": "**Only tritium is radioactive**: low-energy β^– emitter, t½ 12.33 years.","exc": true,"tab": false,"src": "old11","page": 26,"o": "Of these isotopes, only tritium is radioactive and emits low energy β^– particles (t½, 12.33 years)."},{"sec": "Occurrence and isotopes","ids": [76],"t": "Table 9.1: Bond dissociation enthalpy/kJ mol^-1 H2 435.88, D2 443.35. Boiling point/K 20.39, 23.67, 25.0 (H, D, T). Ionization enthalpy 1312 kJ mol^-1; electron gain enthalpy -73 kJ mol^-1; covalent radius 37 pm; ionic radius (H^-) 208 pm.","exc": false,"tab": true,"src": "old11","page": 26,"o": "Table 9.1: Bond dissociation enthalpy/kJ mol^-1 H2 435.88, D2 443.35. Boiling point/K 20.39, 23.67, 25.0 (H, D, T). Ionization enthalpy 1312 kJ mol^-1; electron gain enthalpy -73 kJ mol^-1; covalent radius 37 pm; ionic radius (H^-) 208 pm."},{"sec": "Occurrence and isotopes","ids": [77,78],"t": "Isotopes have the same electronic configuration, so nearly the same chemistry; they differ only in reaction rates (different bond dissociation enthalpy).","exc": false,"tab": false,"src": "old11","page": 27,"o": "Since the isotopes have the same electronic configuration, they have almost the same chemical properties. The only difference is in their rates of reactions, mainly due to their different enthalpy of bond dissociation."},{"sec": "Occurrence and isotopes","ids": [79],"t": "Physical properties differ considerably (large mass differences).","exc": false,"tab": false,"src": "old11","page": 27,"o": "However, in physical properties these isotopes differ considerably due to their large mass differences."},{"sec": "Preparation of dihydrogen","ids": [79,80],"t": "Lab: granulated Zn + dilute HCl. Zn + 2H^+ → Zn^2+ + H2","exc": false,"tab": false,"src": "old11","page": 27,"o": "It is usually prepared by the reaction of granulated zinc with dilute hydrochloric acid. Zn + 2H^+ → Zn^2+ + H2"},{"sec": "Preparation of dihydrogen","ids": [80,81],"t": "Zn + aqueous alkali: Zn + 2NaOH → Na2ZnO2 (sodium zincate) + H2","exc": false,"tab": false,"src": "old11","page": 27,"o": "It can also be prepared by the reaction of zinc with aqueous alkali. Zn + 2NaOH → Na2ZnO2 + H2 (Sodium zincate)"},{"sec": "Preparation of dihydrogen","ids": [81,82],"t": "Electrolysis of acidified water (Pt electrodes): 2H2O(l) → 2H2(g) + O2(g)","exc": false,"tab": false,"src": "old11","page": 27,"o": "Electrolysis of acidified water using platinum electrodes gives hydrogen. 2H2O(l) → 2H2(g) + O2(g) (electrolysis, traces of acid/base)"},{"sec": "Preparation of dihydrogen","ids": [82],"t": "Highest purity (>99.95%) H2: electrolysis of warm aqueous Ba(OH)2 between Ni electrodes.","exc": false,"tab": false,"src": "old11","page": 27,"o": "High purity (>99.95%) dihydrogen is obtained by electrolysing warm aqueous barium hydroxide solution between nickel electrodes."},{"sec": "Preparation of dihydrogen","ids": [83],"t": "By-product of NaOH and Cl2 manufacture by electrolysis of brine.","exc": false,"tab": false,"src": "old11","page": 27,"o": "It is obtained as a byproduct in the manufacture of sodium hydroxide and chlorine by the electrolysis of brine solution."},{"sec": "Preparation of dihydrogen","ids": [84],"t": "Brine electrolysis: anode 2Cl^-(aq) → Cl2(g) + 2e^-; cathode 2H2O(l) + 2e^- → H2(g) + 2OH^-(aq)","exc": false,"tab": false,"src": "old11","page": 27,"o": "At anode: 2Cl^-(aq) → Cl2(g) + 2e^-; at cathode: 2H2O(l) + 2e^- → H2(g) + 2OH^-(aq)"},{"sec": "Preparation of dihydrogen","ids": [84,85],"t": "Steam + hydrocarbons or coke at high T with catalyst: CnH2n+2 + nH2O → nCO + (3n + 1)H2; CH4(g) + H2O(g) → CO(g) + 3H2(g) (1270 K, Ni)","exc": false,"tab": false,"src": "old11","page": 27,"o": "Reaction of steam on hydrocarbons or coke at high temperatures in the presence of catalyst yields hydrogen. CnH2n+2 + nH2O → nCO + (3n + 1)H2, e.g., CH4(g) + H2O(g) → CO(g) + 3H2(g) (1270 K, Ni)"},{"sec": "Preparation of dihydrogen","ids": [85,86],"t": "CO + H2 = water gas; also called synthesis gas ('syngas') since it is used to make methanol and hydrocarbons.","exc": false,"tab": false,"src": "old11","page": 27,"o": "The mixture of CO and H2 is called water gas. As this mixture of CO and H2 is used for the synthesis of methanol and a number of hydrocarbons, it is also called synthesis gas or 'syngas'."},{"sec": "Preparation of dihydrogen","ids": [87],"t": "Syngas from coal = coal gasification: C(s) + H2O(g) → CO(g) + H2(g) (1270 K). Syngas is also made from sewage, saw-dust, scrap wood, newspapers.","exc": false,"tab": false,"src": "old11","page": 27,"o": "Nowadays 'syngas' is produced from sewage, saw-dust, scrap wood, newspapers etc. The process of producing 'syngas' from coal is called 'coal gasification'. C(s) + H2O(g) → CO(g) + H2(g) (1270 K)"},{"sec": "Preparation of dihydrogen","ids": [88],"t": "**Water-gas shift reaction**: CO(g) + H2O(g) → CO2(g) + H2(g) (673 K, iron chromate catalyst); raises the H2 yield.","exc": false,"tab": false,"src": "old11","page": 27,"o": "The production of dihydrogen can be increased by reacting carbon monoxide of syngas mixtures with steam in the presence of iron chromate as catalyst. CO(g) + H2O(g) → CO2(g) + H2(g) (673 K, catalyst). This is called water-gas shift reaction."},{"sec": "Preparation of dihydrogen","ids": [89],"t": "CO2 removed by scrubbing with sodium arsenite solution.","exc": false,"tab": false,"src": "old11","page": 27,"o": "Carbon dioxide is removed by scrubbing with sodium arsenite solution."},{"sec": "Properties of dihydrogen","ids": [90,91],"t": "H2: colourless, odourless, tasteless, combustible; lighter than air; insoluble in water.","exc": false,"tab": false,"src": "old11","page": 27,"o": "Dihydrogen is a colourless, odourless, tasteless, combustible gas. It is lighter than air and insoluble in water."},{"sec": "Properties of dihydrogen","ids": [93],"t": "**H–H bond dissociation enthalpy is the highest for a single bond between two atoms of any element.**","exc": true,"tab": false,"src": "old11","page": 27,"o": "The H-H bond dissociation enthalpy is the highest for a single bond between two atoms of any element."},{"sec": "Properties of dihydrogen","ids": [95,96],"t": "So H2 dissociates only ~0.081% at 2000 K (95.5% at 5000 K), and is fairly inert at room temperature.","exc": false,"tab": false,"src": "old11","page": 27,"o": "It is because of this factor that the dissociation of dihydrogen into its atoms is only ~0.081% around 2000K which increases to 95.5% at 5000K. Also, it is relatively inert at room temperature due to the high H-H bond enthalpy."},{"sec": "Properties of dihydrogen","ids": [97],"t": "Atomic H is made at high T in an electric arc or under UV radiation.","exc": false,"tab": false,"src": "old11","page": 28,"o": "Thus, the atomic hydrogen is produced at a high temperature in an electric arc or under ultraviolet radiations."},{"sec": "Properties of dihydrogen","ids": [98],"t": "Incomplete 1s^1, so it combines with almost all elements.","exc": false,"tab": true,"src": "old11","page": 28,"o": "Since its orbital is incomplete with 1s^1 electronic configuration, it does combine with almost all the elements."},{"sec": "Properties of dihydrogen","ids": [99],"t": "It reacts by (i) losing its electron (H^+), (ii) gaining one (H^-), (iii) sharing to form a single covalent bond.","exc": false,"tab": false,"src": "old11","page": 28,"o": "It accomplishes reactions by (i) loss of the only electron to give H^+, (ii) gain of an electron to form H^-, and (iii) sharing electrons to form a single covalent bond."},{"sec": "Properties of dihydrogen","ids": [100],"t": "H2(g) + X2(g) → 2HX(g). **With F2 even in the dark; with I2 a catalyst is needed.**","exc": true,"tab": false,"src": "old11","page": 28,"o": "It reacts with halogens, X2, to give hydrogen halides, HX: H2(g) + X2(g) → 2HX(g) (X = F, Cl, Br, I). While the reaction with fluorine occurs even in the dark, with iodine it requires a catalyst."},{"sec": "Properties of dihydrogen","ids": [100,101],"t": "2H2(g) + O2(g) → 2H2O(l) (catalyst or heating); highly exothermic, ∆H° = -285.9 kJ mol^-1","exc": false,"tab": false,"src": "old11","page": 28,"o": "It reacts with dioxygen to form water. The reaction is highly exothermic. 2H2(g) + O2(g) → 2H2O(l) (catalyst or heating); ∆H° = -285.9 kJ mol^-1"},{"sec": "Properties of dihydrogen","ids": [101,102],"t": "**Haber process**: 3H2(g) + N2(g) → 2NH3(g) (673 K, 200 atm, Fe); ∆H° = -92.6 kJ mol^-1","exc": false,"tab": false,"src": "old11","page": 28,"o": "With dinitrogen it forms ammonia. 3H2(g) + N2(g) → 2NH3(g) (673K, 200atm, Fe); ∆H° = -92.6 kJ mol^-1. This is the method for the manufacture of ammonia by the Haber process."},{"sec": "Properties of dihydrogen","ids": [103],"t": "With alkali metals at high T: H2(g) + 2M(g) → 2MH(s)","exc": false,"tab": false,"src": "old11","page": 28,"o": "With many metals it combines at a high temperature to yield the corresponding hydrides. H2(g) + 2M(g) → 2MH(s); where M is an alkali metal."},{"sec": "Properties of dihydrogen","ids": [103,104],"t": "Reduces some metal ions and oxides of metals less active than iron: H2(g) + Pd^2+(aq) → Pd(s) + 2H^+(aq); yH2(g) + MxOy(s) → xM(s) + yH2O(l)","exc": false,"tab": false,"src": "old11","page": 28,"o": "It reduces some metal ions in aqueous solution and oxides of metals (less active than iron) into corresponding metals. H2(g) + Pd^2+(aq) → Pd(s) + 2H^+(aq); yH2(g) + MxOy(s) → xM(s) + yH2O(l)"},{"sec": "Properties of dihydrogen","ids": [104,105],"t": "Hydrogenation of vegetable oils (Ni catalyst) gives edible fats (margarine, vanaspati ghee).","exc": false,"tab": false,"src": "old11","page": 28,"o": "It reacts with many organic compounds in the presence of catalysts to give useful hydrogenated products of commercial importance. Hydrogenation of vegetable oils using nickel as catalyst gives edible fats (margarine and vanaspati ghee)."},{"sec": "Properties of dihydrogen","ids": [105,106],"t": "Hydroformylation: H2 + CO + RCH=CH2 → RCH2CH2CHO; then H2 + RCH2CH2CHO → RCH2CH2CH2OH","exc": false,"tab": false,"src": "old11","page": 28,"o": "Hydroformylation of olefins yields aldehydes which further undergo reduction to give alcohols. H2 + CO + RCH=CH2 → RCH2CH2CHO; H2 + RCH2CH2CHO → RCH2CH2CH2OH"},{"sec": "Properties of dihydrogen","ids": [106,107],"t": "With Cl2: H2 is oxidised (to H^+) and Cl2 reduced; HCl is covalent (shared pair).","exc": false,"tab": true,"src": "old11","page": 28,"o": "Dihydrogen reduces chlorine into chloride (Cl^-) ion and itself gets oxidised to H^+ ion by chlorine to form hydrogen chloride. An electron pair is shared between H and Cl leading to the formation of a covalent molecule."},{"sec": "Properties of dihydrogen","ids": [108],"t": "With Na: H2 is reduced; e^- transferred from Na to H, giving ionic NaH.","exc": false,"tab": false,"src": "old11","page": 28,"o": "Dihydrogen is reduced by sodium to form NaH. An electron is transferred from Na to H leading to the formation of an ionic compound, NaH."},{"sec": "Properties of dihydrogen","ids": [109],"t": "With CuO: H2 reduces Cu(II) to Cu(0) and is oxidised to covalent H2O.","exc": false,"tab": true,"src": "old11","page": 28,"o": "Dihydrogen reduces copper(II) oxide to copper in zero oxidation state and itself gets oxidised to H2O, which is a covalent molecule."},{"sec": "Uses of dihydrogen","ids": [109],"t": "Largest single use: synthesis of NH3 (for HNO3 and nitrogenous fertilisers).","exc": false,"tab": false,"src": "old11","page": 28,"o": "The largest single use of dihydrogen is in the synthesis of ammonia which is used in the manufacture of nitric acid and nitrogenous fertilizers."},{"sec": "Uses of dihydrogen","ids": [109],"t": "Vanaspati fat by hydrogenation of polyunsaturated vegetable oils.","exc": false,"tab": false,"src": "old11","page": 28,"o": "Dihydrogen is used in the manufacture of vanaspati fat by the hydrogenation of polyunsaturated vegetable oils like soyabean, cotton seeds etc."},{"sec": "Uses of dihydrogen","ids": [109],"t": "Methanol: CO(g) + 2H2(g) → CH3OH(l) (cobalt catalyst)","exc": false,"tab": false,"src": "old11","page": 28,"o": "It is used in the manufacture of bulk organic chemicals, particularly methanol. CO(g) + 2H2(g) → CH3OH(l) (cobalt catalyst)"},{"sec": "Uses of dihydrogen","ids": [110],"t": "Reduces heavy metal oxides in metallurgy; atomic hydrogen and oxy-hydrogen torches for cutting and welding.","exc": false,"tab": false,"src": "old11","page": 29,"o": "In metallurgical processes, it is used to reduce heavy metal oxides to metals. Atomic hydrogen and oxy-hydrogen torches find use for cutting and welding purposes."},{"sec": "Uses of dihydrogen","ids": [111],"t": "Atomic hydrogen torch: H atoms from an electric arc recombine on the surface being welded, reaching ~4000 K.","exc": false,"tab": false,"src": "old11","page": 29,"o": "Atomic hydrogen atoms (produced by dissociation of dihydrogen with the help of an electric arc) are allowed to recombine on the surface to be welded to generate the temperature of 4000 K."},{"sec": "Uses of dihydrogen","ids": [111],"t": "Rocket fuel; fuel cells for electrical energy.","exc": false,"tab": false,"src": "old11","page": 29,"o": "It is used as a rocket fuel in space research. Dihydrogen is used in fuel cells for generating electrical energy."},{"sec": "Uses of dihydrogen","ids": [113],"t": "As fuel: no pollution, more energy per unit mass than gasoline.","exc": false,"tab": false,"src": "old11","page": 29,"o": "It does not produce any pollution and releases greater energy per unit mass of fuel in comparison to gasoline and other fuels."},{"sec": "Hydrides","ids": [114],"t": "H2 forms binary hydrides with almost all elements **except noble gases**.","exc": false,"tab": false,"src": "old11","page": 29,"o": "Dihydrogen, under certain reaction conditions, combines with almost all elements, except noble gases, to form binary compounds, called hydrides."},{"sec": "Hydrides","ids": [115],"t": "Formula EHx (e.g. MgH2) or EmHn (e.g. B2H6).","exc": false,"tab": true,"src": "old11","page": 29,"o": "If 'E' is the symbol of an element then hydride can be expressed as EHx (e.g., MgH2) or EmHn (e.g., B2H6)."},{"sec": "Hydrides","ids": [116],"t": "Three classes: ionic (saline), covalent (molecular), metallic (non-stoichiometric).","exc": false,"tab": false,"src": "old11","page": 29,"o": "The hydrides are classified into three categories: (i) Ionic or saline or saltlike hydrides (ii) Covalent or molecular hydrides (iii) Metallic or non-stoichiometric hydrides."},{"sec": "Hydrides","ids": [116],"t": "Ionic hydrides: stoichiometric; formed by most s-block (highly electropositive) elements.","exc": false,"tab": false,"src": "old11","page": 29,"o": "Ionic hydrides are stoichiometric compounds of dihydrogen formed with most of the s-block elements which are highly electropositive in character."},{"sec": "Hydrides","ids": [117,118],"t": "**LiH, BeH2, MgH2 have significant covalent character; BeH2 and MgH2 are polymeric.**","exc": true,"tab": false,"src": "old11","page": 29,"o": "However, significant covalent character is found in the lighter metal hydrides such as LiH, BeH2 and MgH2. In fact BeH2 and MgH2 are polymeric in structure."},{"sec": "Hydrides","ids": [119,120],"t": "Ionic hydrides: crystalline, non-volatile, non-conducting as solids; melts conduct and give H2 at the **anode**, proving H^-.","exc": false,"tab": false,"src": "old11","page": 29,"o": "The ionic hydrides are crystalline, non-volatile and nonconducting in solid state. However, their melts conduct electricity and on electrolysis liberate dihydrogen gas at anode, which confirms the existence of H^- ion."},{"sec": "Hydrides","ids": [120,121],"t": "React violently with water: NaH(s) + H2O(aq) → NaOH(aq) + H2(g)","exc": false,"tab": false,"src": "old11","page": 29,"o": "Saline hydrides react violently with water producing dihydrogen gas. NaH(s) + H2O(aq) → NaOH(aq) + H2(g)"},{"sec": "Hydrides","ids": [121,122],"t": "LiH is fairly unreactive with O2/Cl2 at moderate T, so used to make other hydrides: 8LiH + Al2Cl6 → 2LiAlH4 + 6LiCl; 2LiH + B2H6 → 2LiBH4","exc": false,"tab": false,"src": "old11","page": 29,"o": "Lithium hydride is rather unreactive at moderate temperatures with O2 or Cl2. It is, therefore, used in the synthesis of other useful hydrides, e.g., 8LiH + Al2Cl6 → 2LiAlH4 + 6LiCl; 2LiH + B2H6 → 2LiBH4"},{"sec": "Hydrides","ids": [122,123],"t": "Molecular hydrides: with most p-block elements (CH4, NH3, H2O, HF).","exc": false,"tab": false,"src": "old11","page": 29,"o": "Dihydrogen forms molecular compounds with most of the p-block elements. Most familiar examples are CH4, NH3, H2O and HF."},{"sec": "Hydrides","ids": [124],"t": "Covalent, hence volatile.","exc": false,"tab": false,"src": "old11","page": 29,"o": "Being covalent, they are volatile compounds."},{"sec": "Hydrides","ids": [125],"t": "Molecular hydrides: electron-deficient, electron-precise, electron-rich.","exc": false,"tab": false,"src": "old11","page": 29,"o": "Molecular hydrides are further classified according to the relative numbers of electrons and bonds in their Lewis structure into: (i) electron-deficient, (ii) electron-precise, and (iii) electron-rich hydrides."},{"sec": "Hydrides","ids": [126,127,128],"t": "Electron-deficient: too few electrons for a Lewis structure, e.g. B2H6; all group 13 elements form them.","exc": false,"tab": false,"src": "old11","page": 29,"o": "An electron-deficient hydride, as the name suggests, has too few electrons for writing its conventional Lewis structure. Diborane (B2H6) is an example. In fact all elements of group 13 will form electron-deficient compounds."},{"sec": "Hydrides","ids": [130],"t": "Electron-deficient hydrides are Lewis acids.","exc": false,"tab": false,"src": "old11","page": 29,"o": "They act as Lewis acids i.e., electron acceptors."},{"sec": "Hydrides","ids": [131,132],"t": "Electron-precise: exactly enough electrons; group 14 (e.g. CH4), tetrahedral.","exc": false,"tab": false,"src": "old11","page": 29,"o": "Electron-precise compounds have the required number of electrons to write their conventional Lewis structures. All elements of group 14 form such compounds (e.g., CH4) which are tetrahedral in geometry."},{"sec": "Hydrides","ids": [133,134,135],"t": "Electron-rich: lone pairs; groups 15–17 (NH3 1 lp, H2O 2, HF 3).","exc": false,"tab": false,"src": "old11","page": 29,"o": "Electron-rich hydrides have excess electrons which are present as lone pairs. Elements of group 15-17 form such compounds. (NH3 has 1 lone pair, H2O - 2 and HF - 3 lone pairs)."},{"sec": "Hydrides","ids": [137],"t": "Electron-rich hydrides are Lewis bases.","exc": false,"tab": false,"src": "old11","page": 29,"o": "They will behave as Lewis bases i.e., electron donors."},{"sec": "Hydrides","ids": [138,139],"t": "Lone pairs on N, O, F lead to H-bonding and molecular association.","exc": false,"tab": false,"src": "old11","page": 29,"o": "The presence of lone pairs on highly electronegative atoms like N, O and F in hydrides results in hydrogen bond formation between the molecules. This leads to the association of molecules."},{"sec": "Hydrides","ids": [142],"t": "By molar mass alone, NH3, H2O, HF should boil lower than the next members' hydrides.","exc": false,"tab": true,"src": "old11","page": 30,"o": "On the basis of molecular masses of NH3, H2O and HF, their boiling points are expected to be lower than those of the subsequent group member hydrides."},{"sec": "Hydrides","ids": [143,144],"t": "**But H-bonding makes the b.p. of NH3, H2O, HF higher than the hydrides of the next members.**","exc": true,"tab": false,"src": "old11","page": 30,"o": "However, due to higher electronegativity of N, O and F, the magnitude of hydrogen bonding in their hydrides will be quite appreciable. Hence, the boiling points NH3, H2O and HF will be higher than the hydrides of their subsequent group members."},{"sec": "Hydrides","ids": [145,146],"t": "Metallic hydrides: many d- and f-block elements; **groups 7, 8, 9 form none.**","exc": true,"tab": false,"src": "old11","page": 30,"o": "Metallic hydrides are formed by many d-block and f-block elements. However, the metals of group 7, 8 and 9 do not form hydride."},{"sec": "Hydrides","ids": [147],"t": "**In group 6 only Cr forms a hydride (CrH).** Metallic hydrides conduct heat and electricity, less well than the parent metals.","exc": true,"tab": false,"src": "old11","page": 30,"o": "Even from group 6, only chromium forms CrH. These hydrides conduct heat and electricity though not as efficiently as their parent metals do."},{"sec": "Hydrides","ids": [148,149],"t": "Almost always non-stoichiometric (H-deficient): LaH2.87, YbH2.55, TiH1.5-1.8, ZrH1.3-1.75, VH0.56, NiH0.6-0.7, PdH0.6-0.8; law of constant composition fails.","exc": false,"tab": false,"src": "old11","page": 30,"o": "Unlike saline hydrides, they are almost always nonstoichiometric, being deficient in hydrogen. For example, LaH2.87, YbH2.55, TiH1.5-1.8, ZrH1.3-1.75, VH0.56, NiH0.6-0.7, PdH0.6-0.8, etc. In such hydrides, the law of constant composition does not hold good."},{"sec": "Hydrides","ids": [150,151],"t": "Once called interstitial hydrides (H thought to sit in lattice holes without changing the lattice type).","exc": false,"tab": false,"src": "old11","page": 30,"o": "Earlier it was thought that in these hydrides, hydrogen occupies interstices in the metal lattice producing distortion without any change in its type. Consequently, they were termed as interstitial hydrides."},{"sec": "Hydrides","ids": [152],"t": "**Except for Ni, Pd, Ce, Ac hydrides, the lattice differs from the parent metal's.**","exc": true,"tab": false,"src": "old11","page": 30,"o": "However, recent studies have shown that except for hydrides of Ni, Pd, Ce and Ac, other hydrides of this class have lattice different from that of the parent metal."},{"sec": "Hydrides","ids": [152],"t": "H absorption on transition metals is used in catalytic reduction/hydrogenation.","exc": false,"tab": false,"src": "old11","page": 30,"o": "The property of absorption of hydrogen on transition metals is widely used in catalytic reduction / hydrogenation reactions for the preparation of large number of compounds."},{"sec": "Hydrides","ids": [153],"t": "Pd, Pt absorb very large volumes of H2, so they serve as storage media.","exc": false,"tab": false,"src": "old11","page": 30,"o": "Some of the metals (e.g., Pd, Pt) can accommodate a very large volume of hydrogen and, therefore, can be used as its storage media."},{"sec": "Hydrides","ids": [155,156],"t": "**P shows +3 and +5 but PH5 does not exist**: high ∆aH of H2 and ∆egH of H disfavour P's highest oxidation state.","exc": true,"tab": false,"src": "old11","page": 30,"o": "Although phosphorus exhibits +3 and +5 oxidation states, it cannot form PH5. Besides some other considerations, high ∆aH value of dihydrogen and ∆egH value of hydrogen do not favour to exhibit the highest oxidation state of P, and consequently the formation of PH5."},{"sec": "Hydrides","ids": [303],"t": "Metallic hydrides: used for ultrapurification of H2 and as H2 storage.","exc": false,"tab": false,"src": "old11","page": 37,"o": "Metallic hydrides are useful for ultrapurification of dihydrogen and as dihydrogen storage media."},{"sec": "Water","ids": [164],"t": "Water's unusual properties in liquid and solid come from extensive H-bonding.","exc": false,"tab": false,"src": "old11","page": 30,"o": "The unusual properties of water in the condensed phase (liquid and solid states) are due to the presence of extensive hydrogen bonding between water molecules."},{"sec": "Water","ids": [165],"t": "Compared with H2S, H2Se: higher f.p., b.p., heat of vaporisation, heat of fusion. Compared with other liquids: higher specific heat, thermal conductivity, surface tension, dipole moment, dielectric constant.","exc": false,"tab": false,"src": "old11","page": 30,"o": "This leads to high freezing point, high boiling point, high heat of vaporisation and high heat of fusion in comparison to H2S and H2Se. In comparison to other liquids, water has a higher specific heat, thermal conductivity, surface tension, dipole moment and dielectric constant, etc."},{"sec": "Water","ids": [166],"t": "Table 9.3: Melting point/K H2O 273.0, D2O 276.8; boiling point/K 373.0, 374.4; temp of max. density/K 276.98, 284.2; density (298K)/g cm^-3 1.0000, 1.1059; dielectric constant 78.39, 78.06.","exc": false,"tab": true,"src": "old11","page": 31,"o": "Table 9.3: Melting point/K H2O 273.0, D2O 276.8; boiling point/K 373.0, 374.4; temp of max. density/K 276.98, 284.2; density (298K)/g cm^-3 1.0000, 1.1059; dielectric constant 78.39, 78.06."},{"sec": "Water","ids": [168],"t": "Covalent alcohols and carbohydrates dissolve in water through H-bonding.","exc": false,"tab": false,"src": "old11","page": 31,"o": "Due to hydrogen bonding with polar molecules, even covalent compounds like alcohol and carbohydrates dissolve in water."},{"sec": "Water","ids": [169,170],"t": "Gas phase H2O: bent, angle 104.5°, O–H 95.7 pm; highly polar.","exc": false,"tab": false,"src": "old11","page": 31,"o": "In the gas phase water is a bent molecule with a bond angle of 104.5°, and O-H bond length of 95.7 pm. It is a highly polar molecule."},{"sec": "Water","ids": [172,173,174],"t": "Liquid: H-bonded associations. Ice: hexagonal at atmospheric pressure, cubic at very low temperature.","exc": false,"tab": false,"src": "old11","page": 31,"o": "In the liquid phase water molecules are associated together by hydrogen bonds. The crystalline form of water is ice. At atmospheric pressure ice crystallises in the hexagonal form, but at very low temperatures it condenses to cubic form."},{"sec": "Water","ids": [175,176],"t": "**Ice is less dense than water** (floats).","exc": true,"tab": false,"src": "old11","page": 31,"o": "Density of ice is less than that of water. Therefore, an ice cube floats on water."},{"sec": "Water","ids": [177],"t": "Surface ice insulates a lake in winter, so aquatic life survives.","exc": false,"tab": false,"src": "old11","page": 31,"o": "In winter season ice formed on the surface of a lake provides thermal insulation which ensures the survival of the aquatic life."},{"sec": "Water","ids": [179,180,181],"t": "Ice: ordered 3D H-bonded structure; each O is surrounded tetrahedrally by four O at 276 pm.","exc": false,"tab": false,"src": "old11","page": 31,"o": "Ice has a highly ordered three dimensional hydrogen bonded structure. Examination of ice crystals with X-rays shows that each oxygen atom is surrounded tetrahedrally by four other oxygen atoms at a distance of 276 pm."},{"sec": "Water","ids": [182,183],"t": "Open structure with wide holes that can hold small molecules interstitially.","exc": false,"tab": false,"src": "old11","page": 32,"o": "Hydrogen bonding gives ice a rather open type structure with wide holes. These holes can hold some other molecules of appropriate size interstitially."},{"sec": "Water","ids": [186,187],"t": "Water is amphoteric: Brønsted acid with NH3, base with H2S.","exc": false,"tab": false,"src": "old11","page": 32,"o": "It has the ability to act as an acid as well as a base i.e., it behaves as an amphoteric substance. In the Brønsted sense it acts as an acid with NH3 and a base with H2S."},{"sec": "Water","ids": [187],"t": "H2O(l) + NH3(aq) ⇌ OH^-(aq) + NH4^+(aq); H2O(l) + H2S(aq) ⇌ H3O^+(aq) + HS^-(aq)","exc": false,"tab": false,"src": "old11","page": 32,"o": "H2O(l) + NH3(aq) ⇌ OH^-(aq) + NH4^+(aq); H2O(l) + H2S(aq) ⇌ H3O^+(aq) + HS^-(aq)"},{"sec": "Water","ids": [187],"t": "Auto-protolysis: H2O(l) + H2O(l) ⇌ H3O^+(aq) + OH^-(aq)","exc": false,"tab": false,"src": "old11","page": 32,"o": "The auto-protolysis (self-ionization) of water takes place as follows: H2O(l) + H2O(l) ⇌ H3O^+(aq) + OH^-(aq)"},{"sec": "Water","ids": [187],"t": "Reduced to H2 by electropositive metals: 2H2O(l) + 2Na(s) → 2NaOH(aq) + H2(g)","exc": false,"tab": false,"src": "old11","page": 32,"o": "Water can be easily reduced to dihydrogen by highly electropositive metals. 2H2O(l) + 2Na(s) → 2NaOH(aq) + H2(g). Thus, it is a great source of dihydrogen."},{"sec": "Water","ids": [188],"t": "Oxidised to O2 in photosynthesis: 6CO2 + 12H2O → C6H12O6 + 6H2O + 6O2; and by F2: 2F2(g) + 2H2O(l) → 4H^+(aq) + 4F^-(aq) + O2(g)","exc": false,"tab": false,"src": "old11","page": 32,"o": "Water is oxidised to O2 during photosynthesis. 6CO2(g) + 12H2O(l) → C6H12O6(aq) + 6H2O(l) + 6O2(g). With fluorine also it is oxidised to O2. 2F2(g) + 2H2O(l) → 4H^+(aq) + 4F^-(aq) + O2(g)"},{"sec": "Water","ids": [188,189,190],"t": "High dielectric constant: strong hydrating tendency, dissolves many ionic compounds; some covalent and ionic compounds are hydrolysed.","exc": false,"tab": false,"src": "old11","page": 32,"o": "Due to high dielectric constant, it has a very strong hydrating tendency. It dissolves many ionic compounds. However, certain covalent and some ionic compounds are hydrolysed in water."},{"sec": "Water","ids": [191],"t": "P4O10(s) + 6H2O(l) → 4H3PO4(aq); SiCl4(l) + 2H2O(l) → SiO2(s) + 4HCl(aq); N^3-(s) + 3H2O(l) → NH3(g) + 3OH^-(aq)","exc": false,"tab": true,"src": "old11","page": 32,"o": "P4O10(s) + 6H2O(l) → 4H3PO4(aq); SiCl4(l) + 2H2O(l) → SiO2(s) + 4HCl(aq); N^3-(s) + 3H2O(l) → NH3(g) + 3OH^-(aq)"},{"sec": "Water","ids": [191,192],"t": "Water in hydrates: coordinated [Cr(H2O)6]^3+ 3Cl^-; interstitial BaCl2·2H2O; H-bonded [Cu(H2O)4]^2+ SO4^2-·H2O in CuSO4·5H2O.","exc": false,"tab": false,"src": "old11","page": 32,"o": "From aqueous solutions many salts can be crystallised as hydrated salts. Such an association of water is of different types viz., (i) coordinated water e.g., [Cr(H2O)6]^3+ 3Cl^- (ii) interstitial water e.g., BaCl2.2H2O (iii) hydrogen-bonded water e.g., [Cu(H2O)4]^2+ SO4^2-.H2O in CuSO4.5H2O."},{"sec": "Water","ids": [194,195],"t": "**CuSO4·5H2O: 4 H2O coordinated, 1 H-bonded** (outside the coordination sphere).","exc": false,"tab": false,"src": "old11","page": 32,"o": "Only one water molecule, which is outside the brackets (coordination sphere), is hydrogen-bonded. The other four molecules of water are coordinated."},{"sec": "Water","ids": [311],"t": "Water is highly polar because it is bent.","exc": false,"tab": false,"src": "old11","page": 37,"o": "The water molecule is highly polar in nature due to its bent structure."},{"sec": "Water","ids": [312],"t": "H-bonding is maximum in ice, least in vapour.","exc": false,"tab": false,"src": "old11","page": 37,"o": "Hydrogen bonding is the maximum in ice and least in water vapour."},{"sec": "Water","ids": [313],"t": "Polarity makes water a good solvent for ionic/partly ionic compounds, amphoteric, and a former of different hydrate types.","exc": false,"tab": false,"src": "old11","page": 37,"o": "The polar nature of water makes it: (a) a very good solvent for ionic and partially ionic compounds; (b) to act as an amphoteric (acid as well as base) substance; and (c) to form hydrates of different types."},{"sec": "Hard and soft water","ids": [198,199],"t": "Hard water: Ca and Mg hydrogencarbonates, chlorides, sulphates; no lather with soap.","exc": false,"tab": false,"src": "old11","page": 32,"o": "Presence of calcium and magnesium salts in the form of hydrogencarbonate, chloride and sulphate in water makes water 'hard'. Hard water does not give lather with soap."},{"sec": "Hard and soft water","ids": [200,201],"t": "Soft water: no soluble Ca/Mg salts; lathers easily.","exc": false,"tab": false,"src": "old11","page": 32,"o": "Water free from soluble salts of calcium and magnesium is called Soft water. It gives lather with soap easily."},{"sec": "Hard and soft water","ids": [202],"t": "Hard water forms scum with soap.","exc": false,"tab": false,"src": "old11","page": 32,"o": "Hard water forms scum/precipitate with soap."},{"sec": "Hard and soft water","ids": [203],"t": "2C17H35COONa(aq) + M^2+(aq) → (C17H35COO)2M↓ + 2Na^+(aq) (M = Ca/Mg); unsuitable for laundry.","exc": false,"tab": false,"src": "old11","page": 32,"o": "Soap containing sodium stearate (C17H35COONa) reacts with hard water to precipitate out Ca/Mg stearate. 2C17H35COONa(aq) + M^2+(aq) → (C17H35COO)2M↓ + 2Na^+(aq); M is Ca/Mg. It is, therefore, unsuitable for laundry."},{"sec": "Hard and soft water","ids": [204,205],"t": "Forms scale in boilers, lowering efficiency.","exc": false,"tab": false,"src": "old11","page": 32,"o": "It is harmful for boilers as well, because of deposition of salts in the form of scale. This reduces the efficiency of the boiler."},{"sec": "Hard and soft water","ids": [207,208],"t": "Temporary hardness: Mg and Ca hydrogencarbonates. Permanent: chlorides and sulphates.","exc": false,"tab": false,"src": "old11","page": 33,"o": "The hardness of water is of two types: (i) temporary hardness, and (ii) permanent hardness. Temporary hardness is due to the presence of magnesium and calcium hydrogencarbonates."},{"sec": "Hard and soft water","ids": [209],"t": "Boiling: Mg(HCO3)2 → insoluble Mg(OH)2; Ca(HCO3)2 → insoluble CaCO3.","exc": false,"tab": false,"src": "old11","page": 33,"o": "During boiling, the soluble Mg(HCO3)2 is converted into insoluble Mg(OH)2 and Ca(HCO3)2 is changed to insoluble CaCO3."},{"sec": "Hard and soft water","ids": [210],"t": "**Mg gives Mg(OH)2, not MgCO3**: Mg(OH)2 has the lower solubility (Ksp of MgCO3 is higher).","exc": true,"tab": false,"src": "old11","page": 33,"o": "It is because of high solubility product of Mg(OH)2 as compared to that of MgCO3, that Mg(OH)2 is precipitated."},{"sec": "Hard and soft water","ids": [213],"t": "Mg(HCO3)2 → Mg(OH)2↓ + 2CO2↑ (heating); Ca(HCO3)2 → CaCO3↓ + H2O + CO2↑ (heating)","exc": false,"tab": true,"src": "old11","page": 33,"o": "Mg(HCO3)2 → Mg(OH)2↓ + 2CO2↑ (heating); Ca(HCO3)2 → CaCO3↓ + H2O + CO2↑ (heating)"},{"sec": "Hard and soft water","ids": [213,214],"t": "Clark's method: calculated amount of lime precipitates CaCO3 and Mg(OH)2.","exc": false,"tab": false,"src": "old11","page": 33,"o": "Clark's method: In this method calculated amount of lime is added to hard water. It precipitates out calcium carbonate and magnesium hydroxide which can be filtered off."},{"sec": "Hard and soft water","ids": [215],"t": "Ca(HCO3)2 + Ca(OH)2 → 2CaCO3↓ + 2H2O; Mg(HCO3)2 + 2Ca(OH)2 → 2CaCO3↓ + Mg(OH)2↓ + 2H2O","exc": false,"tab": false,"src": "old11","page": 33,"o": "Ca(HCO3)2 + Ca(OH)2 → 2CaCO3↓ + 2H2O; Mg(HCO3)2 + 2Ca(OH)2 → 2CaCO3↓ + Mg(OH)2↓ + 2H2O"},{"sec": "Hard and soft water","ids": [215,216],"t": "Permanent hardness (Ca/Mg chlorides and sulphates) is not removed by boiling.","exc": false,"tab": false,"src": "old11","page": 33,"o": "Permanent hardness is due to the presence of soluble salts of magnesium and calcium in the form of chlorides and sulphates in water. Permanent hardness is not removed by boiling."},{"sec": "Hard and soft water","ids": [217,218],"t": "Washing soda: MCl2 + Na2CO3 → MCO3↓ + 2NaCl; MSO4 + Na2CO3 → MCO3↓ + Na2SO4","exc": false,"tab": false,"src": "old11","page": 33,"o": "Washing soda reacts with soluble calcium and magnesium chlorides and sulphates in hard water to form insoluble carbonates. MCl2 + Na2CO3 → MCO3↓ + 2NaCl (M = Mg, Ca); MSO4 + Na2CO3 → MCO3↓ + Na2SO4"},{"sec": "Hard and soft water","ids": [218,219],"t": "Calgon (Na6P6O18): Na6P6O18 → 2Na^+ + Na4P6O18^2-; M^2+ + Na4P6O18^2- → [Na2MP6O18]^2- + 2Na^+. The complex anion keeps Mg^2+, Ca^2+ in solution.","exc": false,"tab": false,"src": "old11","page": 33,"o": "Calgon's method: Sodium hexametaphosphate (Na6P6O18), commercially called 'calgon', when added to hard water, the following reactions take place. Na6P6O18 → 2Na^+ + Na4P6O18^2-; M^2+ + Na4P6O18^2- → [Na2MP6O18]^2- + 2Na^+ (M = Mg, Ca). The complex anion keeps the Mg^2+ and Ca^2+ ions in solution."},{"sec": "Hard and soft water","ids": [220,221],"t": "Zeolite/permutit process: hydrated sodium aluminium silicate.","exc": false,"tab": false,"src": "old11","page": 33,"o": "Ion-exchange method: This method is also called zeolite/permutit process. Hydrated sodium aluminium silicate is zeolite/permutit."},{"sec": "Hard and soft water","ids": [222],"t": "NaAlSiO4 written as NaZ: 2NaZ(s) + M^2+(aq) → MZ2(s) + 2Na^+(aq)","exc": false,"tab": false,"src": "old11","page": 33,"o": "For the sake of simplicity, sodium aluminium silicate (NaAlSiO4) can be written as NaZ. When this is added in hard water, exchange reactions take place. 2NaZ(s) + M^2+(aq) → MZ2(s) + 2Na^+(aq) (M = Mg, Ca)"},{"sec": "Hard and soft water","ids": [222,223,224],"t": "Exhausted when all Na is used; regenerated with NaCl: MZ2(s) + 2NaCl(aq) → 2NaZ(s) + MCl2(aq)","exc": false,"tab": false,"src": "old11","page": 33,"o": "Permutit/zeolite is said to be exhausted when all the sodium in it is used up. It is regenerated for further use by treating with an aqueous sodium chloride solution. MZ2(s) + 2NaCl(aq) → 2NaZ(s) + MCl2(aq)"},{"sec": "Hard and soft water","ids": [224,225,226],"t": "Synthetic cation exchange resins (–SO3H, water-insoluble) are more efficient than zeolite.","exc": false,"tab": false,"src": "old11","page": 33,"o": "Synthetic resins method: Nowadays hard water is softened by using synthetic cation exchangers. This method is more efficient than zeolite process. Cation exchange resins contain large organic molecule with -SO3H group and are water insoluble."},{"sec": "Hard and soft water","ids": [227,228],"t": "RSO3H → RNa with NaCl; 2RNa(s) + M^2+(aq) → R2M(s) + 2Na^+(aq)","exc": false,"tab": false,"src": "old11","page": 33,"o": "Ion exchange resin (RSO3H) is changed to RNa by treating it with NaCl. The resin exchanges Na^+ ions with Ca^2+ and Mg^2+ ions present in hard water to make the water soft. 2RNa(s) + M^2+(aq) → R2M(s) + 2Na^+(aq)"},{"sec": "Hard and soft water","ids": [229],"t": "Deionised water: cation exchanger (H^+ form) then anion exchanger (OH^- form). 2RH(s) + M^2+(aq) ⇌ MR2(s) + 2H^+(aq)","exc": false,"tab": false,"src": "old11","page": 33,"o": "Pure de-mineralised (de-ionized) water free from all soluble mineral salts is obtained by passing water successively through a cation exchange (in the H^+ form) and an anion exchange (in the OH^- form) resins: 2RH(s) + M^2+(aq) ⇌ MR2(s) + 2H^+(aq)"},{"sec": "Hard and soft water","ids": [230],"t": "The cation step releases H^+, making the water acidic.","exc": false,"tab": false,"src": "old11","page": 33,"o": "This process results in proton release and thus makes the water acidic."},{"sec": "Hard and soft water","ids": [232,233],"t": "Anion exchange: RNH2 + H2O ⇌ RNH3^+·OH^-; RNH3^+·OH^- + X^- ⇌ RNH3^+·X^- + OH^-; the OH^- neutralises the H^+.","exc": false,"tab": false,"src": "old11","page": 34,"o": "RNH2(s) + H2O(l) ⇌ RNH3^+.OH^-(s); RNH3^+.OH^-(s) + X^-(aq) ⇌ RNH3^+.X^-(s) + OH^-(aq). OH^- ions, thus, liberated neutralise the H^+ ions set free in the cation exchange."},{"sec": "Hard and soft water","ids": [234],"t": "Regenerate: cation bed with dilute acid, anion bed with dilute alkali.","exc": false,"tab": false,"src": "old11","page": 34,"o": "The exhausted cation and anion exchange resin beds are regenerated by treatment with dilute acid and alkali solutions respectively."},{"sec": "Hard and soft water","ids": [315],"t": "Zeolites and synthetic ion-exchangers remove both temporary and permanent hardness.","exc": false,"tab": false,"src": "old11","page": 37,"o": "Both temporary and permanent hardness can be removed by the use of zeolites, and synthetic ion-exchangers."},{"sec": "Hydrogen peroxide","ids": [237,238],"t": "BaO2·8H2O(s) + H2SO4(aq) → BaSO4(s) + H2O2(aq) + 8H2O(l) (excess water removed under reduced pressure)","exc": false,"tab": false,"src": "old11","page": 34,"o": "Acidifying barium peroxide and removing excess water by evaporation under reduced pressure gives hydrogen peroxide. BaO2.8H2O(s) + H2SO4(aq) → BaSO4(s) + H2O2(aq) + 8H2O(l)"},{"sec": "Hydrogen peroxide","ids": [238],"t": "Electrolytic oxidation of acidified sulphate at high current density gives peroxodisulphate, which hydrolyses to H2O2.","exc": false,"tab": false,"src": "old11","page": 34,"o": "Peroxodisulphate, obtained by electrolytic oxidation of acidified sulphate solutions at high current density, on hydrolysis yields hydrogen peroxide."},{"sec": "Hydrogen peroxide","ids": [239],"t": "2HSO4^- → HO3SOOSO3H (electrolysis) → 2HSO4^- + 2H^+ + H2O2 (hydrolysis). Now used for lab preparation of D2O2.","exc": false,"tab": false,"src": "old11","page": 34,"o": "2HSO4^-(aq) → HO3SOOSO3H(aq) (electrolysis) → 2HSO4^-(aq) + 2H^+(aq) + H2O2(aq) (hydrolysis). This method is now used for the laboratory preparation of D2O2."},{"sec": "Hydrogen peroxide","ids": [240],"t": "K2S2O8(s) + 2D2O(l) → 2KDSO4(aq) + D2O2(l)","exc": false,"tab": true,"src": "old11","page": 34,"o": "K2S2O8(s) + 2D2O(l) → 2KDSO4(aq) + D2O2(l)"},{"sec": "Hydrogen peroxide","ids": [240],"t": "Industrial: auto-oxidation of 2-alkylanthraquinols: 2-ethylanthraquinol ⇌ H2O2 + oxidised product (1% H2O2).","exc": false,"tab": false,"src": "old11","page": 34,"o": "Industrially it is prepared by the autooxidation of 2-alklylanthraquinols. 2-ethylanthraquinol ⇌ H2O2 + (oxidised product). In this case 1% H2O2 is formed."},{"sec": "Hydrogen peroxide","ids": [241,242,243],"t": "Concentrated to ~30% by distillation under reduced pressure, ~85% at low pressure; remaining water frozen out for pure H2O2.","exc": false,"tab": false,"src": "old11","page": 34,"o": "It is extracted with water and concentrated to ~30% (by mass) by distillation under reduced pressure. It can be further concentrated to ~85% by careful distillation under low pressure. The remaining water can be frozen out to obtain pure H2O2."},{"sec": "Hydrogen peroxide","ids": [244],"t": "Pure H2O2: almost colourless (very pale blue) liquid.","exc": false,"tab": false,"src": "old11","page": 34,"o": "In the pure state H2O2 is an almost colourless (very pale blue) liquid."},{"sec": "Hydrogen peroxide","ids": [246],"t": "Miscible with water in all proportions; hydrate H2O2·H2O (m.p. 221 K).","exc": false,"tab": false,"src": "old11","page": 34,"o": "H2O2 is miscible with water in all proportions and forms a hydrate H2O2.H2O (mp 221K)."},{"sec": "Hydrogen peroxide","ids": [247,248],"t": "30% H2O2 = '100 volume' (1 mL gives 100 mL O2 at STP); commercial 10 V = 3% H2O2.","exc": false,"tab": false,"src": "old11","page": 34,"o": "A 30% solution of H2O2 is marketed as '100 volume' hydrogen peroxide. It means that one millilitre of 30% H2O2 solution will give 100 V of oxygen at STP. Commercially, it is marketed as 10 V, which means it contains 3% H2O2."},{"sec": "Hydrogen peroxide","ids": [250],"t": "H2O2 is non-planar.","exc": false,"tab": false,"src": "old11","page": 35,"o": "Hydrogen peroxide has a non-planar structure."},{"sec": "Hydrogen peroxide","ids": [251,252],"t": "Dihedral angle: 111.5° (gas), 90.2° (solid, 110 K).","exc": false,"tab": false,"src": "old11","page": 35,"o": "H2O2 structure in gas phase, dihedral angle is 111.5°. H2O2 structure in solid phase at 110K, dihedral angle is 90.2°."},{"sec": "Hydrogen peroxide","ids": [252],"t": "Oxidant and reductant in both acidic and basic media.","exc": false,"tab": false,"src": "old11","page": 35,"o": "It acts as an oxidising as well as reducing agent in both acidic and alkaline media."},{"sec": "Hydrogen peroxide","ids": [254],"t": "Oxidising action in acidic medium: 2Fe^2+(aq) + 2H^+(aq) + H2O2(aq) → 2Fe^3+(aq) + 2H2O(l); PbS(s) + 4H2O2(aq) → PbSO4(s) + 4H2O(l)","exc": false,"tab": false,"src": "old11","page": 35,"o": "Oxidising action in acidic medium: 2Fe^2+(aq) + 2H^+(aq) + H2O2(aq) → 2Fe^3+(aq) + 2H2O(l); PbS(s) + 4H2O2(aq) → PbSO4(s) + 4H2O(l)"},{"sec": "Hydrogen peroxide","ids": [254],"t": "Reducing action in acidic medium: 2MnO4^- + 6H^+ + 5H2O2 → 2Mn^2+ + 8H2O + 5O2; HOCl + H2O2 → H3O^+ + Cl^- + O2","exc": false,"tab": true,"src": "old11","page": 35,"o": "Reducing action in acidic medium: 2MnO4^- + 6H^+ + 5H2O2 → 2Mn^2+ + 8H2O + 5O2; HOCl + H2O2 → H3O^+ + Cl^- + O2"},{"sec": "Hydrogen peroxide","ids": [254],"t": "Oxidising action in basic medium: 2Fe^2+ + H2O2 → 2Fe^3+ + 2OH^-; Mn^2+ + H2O2 → Mn^4+ + 2OH^-","exc": false,"tab": false,"src": "old11","page": 35,"o": "Oxidising action in basic medium: 2Fe^2+ + H2O2 → 2Fe^3+ + 2OH^-; Mn^2+ + H2O2 → Mn^4+ + 2OH^-"},{"sec": "Hydrogen peroxide","ids": [254],"t": "Reducing action in basic medium: I2 + H2O2 + 2OH^- → 2I^- + 2H2O + O2; 2MnO4^- + 3H2O2 → 2MnO2 + 3O2 + 2H2O + 2OH^-","exc": false,"tab": true,"src": "old11","page": 35,"o": "Reducing action in basic medium: I2 + H2O2 + 2OH^- → 2I^- + 2H2O + O2; 2MnO4^- + 3H2O2 → 2MnO2 + 3O2 + 2H2O + 2OH^-"},{"sec": "Hydrogen peroxide","ids": [254],"t": "Decomposes slowly in light: 2H2O2(l) → 2H2O(l) + O2(g); catalysed by metal surfaces or traces of alkali (from glass).","exc": false,"tab": false,"src": "old11","page": 35,"o": "H2O2 decomposes slowly on exposure to light. 2H2O2(l) → 2H2O(l) + O2(g). In the presence of metal surfaces or traces of alkali (present in glass containers), the above reaction is catalysed."},{"sec": "Hydrogen peroxide","ids": [255,256,257],"t": "Stored in wax-lined glass or plastic vessels in the dark; urea as stabiliser; kept from dust (can cause explosive decomposition).","exc": false,"tab": false,"src": "old11","page": 35,"o": "It is, therefore, stored in wax-lined glass or plastic vessels in dark. Urea can be added as a stabiliser. It is kept away from dust because dust can induce explosive decomposition of the compound."},{"sec": "Hydrogen peroxide","ids": [258,259],"t": "Hair bleach, mild disinfectant; antiseptic sold as perhydrol.","exc": false,"tab": false,"src": "old11","page": 35,"o": "In daily life it is used as a hair bleach and as a mild disinfectant. As an antiseptic it is sold in the market as perhydrol."},{"sec": "Hydrogen peroxide","ids": [260],"t": "Used to make sodium perborate and percarbonate (detergents).","exc": false,"tab": false,"src": "old11","page": 35,"o": "It is used to manufacture chemicals like sodium perborate and per-carbonate, which are used in high quality detergents."},{"sec": "Hydrogen peroxide","ids": [261],"t": "Used in synthesis of hydroquinone, tartaric acid, cephalosporin; bleach for textiles, paper pulp, leather, oils, fats.","exc": false,"tab": false,"src": "old11","page": 35,"o": "It is used in the synthesis of hydroquinone, tartaric acid and certain food products and pharmaceuticals (cephalosporin) etc. It is employed in the industries as a bleaching agent for textiles, paper pulp, leather, oils, fats, etc."},{"sec": "Hydrogen peroxide","ids": [262],"t": "Pollution control: oxidation of cyanides, restoring aerobic conditions in sewage.","exc": false,"tab": false,"src": "old11","page": 35,"o": "In pollution control treatment of domestic and industrial effluents, oxidation of cyanides, restoration of aerobic conditions to sewage wastes, etc."},{"sec": "Heavy water","ids": [262],"t": "D2O: moderator in nuclear reactors; exchange reactions to study mechanisms.","exc": false,"tab": false,"src": "old11","page": 35,"o": "Heavy water is extensively used as a moderator in nuclear reactors and in exchange reactions for the study of reaction mechanisms."},{"sec": "Heavy water","ids": [263],"t": "Made by exhaustive electrolysis of water, or as a fertiliser-industry by-product.","exc": false,"tab": false,"src": "old11","page": 35,"o": "It can be prepared by exhaustive electrolysis of water or as a by-product in some fertilizer industries."},{"sec": "Heavy water","ids": [265],"t": "Makes deuterium compounds: CaC2 + 2D2O → C2D2 + Ca(OD)2; SO3 + D2O → D2SO4; Al4C3 + 12D2O → 3CD4 + 4Al(OD)3","exc": false,"tab": false,"src": "old11","page": 35,"o": "It is used for the preparation of other deuterium compounds, for example: CaC2 + 2D2O → C2D2 + Ca(OD)2; SO3 + D2O → D2SO4; Al4C3 + 12D2O → 3CD4 + 4Al(OD)3"},{"sec": "Heavy water","ids": [316,317],"t": "D2O is made by electrolytic enrichment of normal water.","exc": false,"tab": false,"src": "old11","page": 37,"o": "Heavy water, D2O is another important compound which is manufactured by the electrolytic enrichment of normal water. It is essentially used as a moderator in nuclear reactors."},{"sec": "Dihydrogen as a fuel","ids": [268,269],"t": "Mass for mass, H2 releases ~3× the energy of petrol, with fewer pollutants.","exc": false,"tab": false,"src": "old11","page": 36,"o": "On a mass for mass basis dihydrogen can release more energy than petrol (about three times). Moreover, pollutants in combustion of dihydrogen will be less than petrol."},{"sec": "Dihydrogen as a fuel","ids": [270,271],"t": "Only pollutants: oxides of nitrogen (N2 impurity); minimised by injecting water to lower cylinder temperature.","exc": false,"tab": false,"src": "old11","page": 36,"o": "The only pollutants will be the oxides of dinitrogen (due to the presence of dinitrogen as impurity with dihydrogen). This, of course, can be minimised by injecting a small amount of water into the cylinder to lower the temperature so that the reaction between dinitrogen and dioxygen may not take place."},{"sec": "Dihydrogen as a fuel","ids": [274,275],"t": "Liquefied at 20 K; stored in small quantities in alloys NaNi5, Ti–TiH2, Mg–MgH2.","exc": false,"tab": false,"src": "old11","page": 36,"o": "Also, dihydrogen gas is converted into liquid state by cooling to 20K. Tanks of metal alloy like NaNi5, Ti-TiH2, Mg-MgH2 etc. are in use for storage of dihydrogen in small quantities."},{"sec": "Dihydrogen as a fuel","ids": [278,279],"t": "Hydrogen economy: energy transported and stored as liquid or gaseous H2, not as electric power.","exc": false,"tab": false,"src": "old11","page": 36,"o": "The basic principle of hydrogen economy is the transportation and storage of energy in the form of liquid or gaseous dihydrogen. Advantage of hydrogen economy is that energy is transmitted in the form of dihydrogen and not as electric power."},{"sec": "Dihydrogen as a fuel","ids": [285],"t": "Energy released on combustion in kJ per gram: dihydrogen (gas) 143, dihydrogen (liquid) 142, LPG 50, CH4 gas 53, octane (liquid) 47.","exc": false,"tab": true,"src": "old11","page": 36,"o": "Energy released on combustion in kJ per gram: dihydrogen (gas) 143, dihydrogen (liquid) 142, LPG 50, CH4 gas 53, octane (liquid) 47."}]);
})();
